<?php use Luna\Core\Csrf; use Luna\Core\View; $token=View::e(Csrf::token()); ?>
<div class="page-actions"><a class="button" href="/documents/<?= View::e($type) ?>">← Elenco</a><div class="inline-actions"><a class="button" href="/documents/<?= View::e($type) ?>/<?= (int)$document['id'] ?>/pdf">PDF</a><?php if(in_array($definition['code'],['SALES_INVOICE','CREDIT_NOTE'],true)):?><a class="button" href="/documents/<?= View::e($type) ?>/<?= (int)$document['id'] ?>/xml">XML FatturaPA</a><?php endif;?><a class="button" href="/operations/communications">Invia e-mail</a><?php if(in_array($definition['code'],['SALES_ORDER','DDT'],true)):?><a class="button" href="/operations/logistics">Picking</a><?php endif;?></div></div>
<section class="card document-head"><div><span class="eyebrow"><?= View::e($definition['singular']) ?></span><h1><?= View::e($document['number']) ?></h1><p><?= View::e($document['counterparty_name']) ?> · <?= View::date($document['document_date']) ?></p></div><div class="document-total"><span>Totale</span><strong><?= View::money($document['total']) ?></strong><span class="badge status-<?= strtolower($document['status']) ?>"><?= View::e($document['status']) ?></span><?php if(($document['fulfillment_status']??'NOT_REQUIRED')!=='NOT_REQUIRED'):?><span class="badge status-<?= strtolower($document['fulfillment_status']) ?>"><?= View::e($document['fulfillment_status']) ?></span><?php endif;?></div></section>
<section class="card table-wrap"><table><thead><tr><th>#</th><th>Descrizione</th><th>Quantità</th><th>Convertita</th><th>Evasa</th><th>Prezzo</th><th>Imponibile</th><th>IVA</th><th>Totale</th></tr></thead><tbody><?php foreach($lines as $line):?><tr><td><?= (int)$line['line_number'] ?></td><td class="primary-cell"><?= View::e($line['description']) ?></td><td><?= View::e($line['quantity'].' '.$line['unit']) ?></td><td><?= View::e($line['converted_quantity']??0) ?></td><td><?= View::e($line['fulfilled_quantity']??0) ?></td><td><?= View::money($line['unit_price']) ?></td><td><?= View::money($line['taxable_amount']) ?></td><td><?= View::e($line['vat_rate']) ?>%</td><td><?= View::money($line['total_amount']) ?></td></tr><?php endforeach;?></tbody><tfoot><tr><td colspan="6"></td><th>Imponibile</th><td colspan="2"><?= View::money($document['taxable_total']) ?></td></tr><tr><td colspan="6"></td><th>IVA</th><td colspan="2"><?= View::money($document['vat_total']) ?></td></tr><tr><td colspan="6"></td><th>Totale</th><td colspan="2"><strong><?= View::money($document['total']) ?></strong></td></tr></tfoot></table></section>
<?php if($conversionTargets!==[]):?><section class="card form-card"><div class="card-header"><div><h2>Conversione guidata</h2><p>Puoi convertire anche quantità parziali; Luna conserva la catena e impedisce sovra-conversioni.</p></div></div><form method="post" action="/documents/<?= View::e($type) ?>/<?= (int)$document['id'] ?>/convert"><input type="hidden" name="_token" value="<?= $token ?>"><div class="form-grid"><label class="field">Destinazione<select name="target_type"><?php foreach($conversionTargets as $target):?><option value="<?= View::e($target) ?>"><?= View::e($targetSlugs[$target]['label']??$target) ?></option><?php endforeach;?></select></label><label class="field">Data documento<input type="date" name="document_date" value="<?= date('Y-m-d') ?>"></label><label class="field">Magazzino<select name="warehouse_id"><option value="">Non assegnato</option><?php foreach($warehouses as $w):?><option value="<?= (int)$w['id'] ?>"><?= View::e($w['code'].' · '.$w['name']) ?></option><?php endforeach;?></select></label></div><div class="table-wrap"><table><thead><tr><th>Riga</th><th>Quantità origine</th><th>Già convertita</th><th>Quantità da convertire</th></tr></thead><tbody><?php foreach($lines as $line):$remaining=max(0,(float)$line['quantity']-(float)($line['converted_quantity']??0));?><tr><td><?= View::e($line['description']) ?></td><td><?= View::e($line['quantity']) ?></td><td><?= View::e($line['converted_quantity']??0) ?></td><td><input type="number" name="quantities[<?= (int)$line['id'] ?>]" value="<?= View::e($remaining) ?>" min="0" max="<?= View::e($remaining) ?>" step="0.0001"></td></tr><?php endforeach;?></tbody></table></div><div class="form-actions"><button class="button primary">Crea documento collegato</button></div></form></section><?php endif;?>
<?php if($outgoingLinks!==[]||$incomingLinks!==[]):?><section class="card"><div class="card-header"><h2>Catena documentale</h2></div><div class="table-wrap"><table><thead><tr><th>Direzione</th><th>Tipo</th><th>Numero</th><th>Data</th></tr></thead><tbody><?php foreach($incomingLinks as $l):?><tr><td>Origine</td><td><?= View::e($l['document_type']) ?></td><td class="primary-cell"><?= View::e($l['number']) ?></td><td><?= View::date($l['document_date']) ?></td></tr><?php endforeach;?><?php foreach($outgoingLinks as $l):?><tr><td>Destinazione</td><td><?= View::e($l['document_type']) ?></td><td class="primary-cell"><?= View::e($l['number']) ?></td><td><?= View::date($l['document_date']) ?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>
<section class="card form-card"><div class="card-header"><div><h2>Aggiorna stato</h2><p>L’emissione/ricezione fattura genera la scrittura contabile se il piano dei conti è configurato.</p></div></div><form method="post" action="/documents/<?= View::e($type) ?>/<?= (int)$document['id'] ?>/status" class="form-grid"><input type="hidden" name="_token" value="<?= $token ?>"><label class="field">Stato<select name="status"><?php foreach(['DRAFT','SENT','ACCEPTED','REJECTED','CONFIRMED','IN_PROGRESS','FULFILLED','ISSUED','RECEIVED','PARTIALLY_PAID','PAID','OVERDUE','CANCELLED'] as $status):?><option <?= $status===$document['status']?'selected':'' ?>><?= $status ?></option><?php endforeach;?></select></label><div class="form-actions"><button class="button primary">Aggiorna</button></div></form></section>
